import{_ as t,o,c as a,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/PDF-PostScript-SVG-and-PNG-Output-Options.md","filePath":"manual-en/PDF-PostScript-SVG-and-PNG-Output-Options.md","lastUpdated":1785684581000}'),s={name:"manual-en/PDF-PostScript-SVG-and-PNG-Output-Options.md"};function n(p,e,r,d,l,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h3 id="_3-2-pdf-postscript-svg-and-png-output-options" tabindex="-1">3.2 PDF, PostScript, SVG, and PNG Output Options <a class="header-anchor" href="#_3-2-pdf-postscript-svg-and-png-output-options" aria-label="Permalink to &quot;3.2 PDF, PostScript, SVG, and PNG Output Options&quot;">​</a></h3><p>To produce output in PDF, PostScript, SVG, or PNG format, specify -o file on the PSPP command line, optionally followed by any of the options shown in the table below to customize the output format.</p><p>PDF, PostScript, and SVG use real units: each dimension among the options listed below may have a suffix ‘mm’ for millimeters, ‘in’ for inches, or ‘pt’ for points. Lacking a suffix, numbers below 50 are assumed to be in inches and those above 50 are assumed to be in millimeters.</p><p>PNG files are pixel-based, so dimensions in PNG output must ultimately be measured in pixels. For output to these files, PSPP translates the specified dimensions to pixels at 72 pixels per inch. For PNG output only, fonts are by default rendered larger than this, at 96 pixels per inch.</p><p>An SVG or PNG file can only hold a single page. When PSPP outputs more than one page to SVG or PNG, it creates multiple files. It outputs the second page to a file named with a <code>-2</code> suffix, the third with a <code>-3</code> suffix, and so on.</p><p>-O format={pdf|ps|svg|png}</p><p>Specify the output format. This is only necessary if the file name given on -o does not end in .pdf, .ps, .svg, or .png.</p><p>-O paper-size=paper-size</p><p>Paper size, as a name (<em>e.g.</em> <code>a4</code>, <code>letter</code>) or measurements (<em>e.g.</em> <code>210x297</code>, <code>8.5x11in</code>).</p><p>The default paper size is taken from the <code>PAPERSIZE</code> environment variable or the file indicated by the <code>PAPERCONF</code> environment variable, if either variable is set. If not, and your system supports the <code>LC_PAPER</code> locale category, then the default paper size is taken from the locale. Otherwise, if /etc/papersize exists, the default paper size is read from it. As a last resort, A4 paper is assumed.</p><p>-O foreground-color=color</p><p>Sets color as the default color for lines and text. Use a CSS color format (e.g. <code>#rrggbb</code>) or name (e.g. <code>black</code>) as color.</p><p>-O orientation=orientation</p><p>Either <code>portrait</code> or <code>landscape</code>. Default: <code>portrait</code>.</p><p>-O left-margin=dimension -O right-margin=dimension -O top-margin=dimension -O bottom-margin=dimension</p><p>Sets the margins around the page. See below for the allowed forms of dimension. Default: <code>0.5in</code>.</p><p>-O object-spacing=dimension</p><p>Sets the amount of vertical space between objects (such as headings or tables).</p><p>-O prop-font=font-name</p><p>Sets the default font used for ordinary text. Most systems support CSS-like font names such as “Sans Serif”, but a wide range of system-specific fonts are likely to be supported as well.</p><p>Default: proportional font <code>Sans Serif</code>.</p><p>-O font-size=font-size</p><p>Sets the size of the default fonts, in thousandths of a point. Default: 10000 (10 point).</p><p>-O trim=true</p><p>This option makes PSPP trim empty space around each page of output, before adding the margins. This can make the output easier to include in other documents.</p><p>-O outline=boolean</p><p>For PDF output only, this option controls whether PSPP includes an outline in the output file. PDF viewers usually display the outline as a side bar that allows for easy navigation of the file. The default is true unless -O trim=true is also specified. (The Cairo graphics library that PSPP uses to produce PDF output has a bug that can cause a crash when outlines and trimming are used together.)</p><p>-O font-resolution=dpi</p><p>Sets the resolution for font rendering, in dots per inch. For PDF, PostScript, and SVG output, the default is 72 dpi, so that a 10-point font is rendered with a height of 10 points. For PNG output, the default is 96 dpi, so that a 10-point font is rendered with a height of <em>10 / 72 * 96 = 13.3</em> pixels. Use a larger dpi to enlarge text output, or a smaller dpi to shrink it.</p>',29)])])}const h=t(s,[["render",n]]);export{f as __pageData,h as default};
